// Extract input values from the incoming webhook payload
const payload = items[0].json;
return [{ json: {
  company_name: payload.company_name || payload.company || '',
  domain: payload.domain || '',
  linkedin_url: payload.linkedin_url || payload.linkedin || '',
  source: payload.source || 'webhook'
}}];

// Decide whether the lead is prequalified and attach a boolean flag
const source = $json.source || '';
const prequalified = source === 'manual-intake' || source === 'marketing';
return [{ json: { prequalified } }];

// Build structured messages for Anthropic Messages API, embedding extraction schema and the system prompt, include enrichment content if present
const system = `You are a lead qualification assistant. Given a company profile and sales signals, extract the following structured fields exactly as JSON: industry, tech_stack_signals, pain_points, buying_signals, icp_fit_score, and score_reasoning. Use the data available from discovery and enrichment only. Do not add extra fields or commentary.`;
const schema = {
  type: 'object',
  properties: {
    industry: { type: 'string' },
    tech_stack_signals: { type: 'array', items: { type: 'string' } },
    pain_points: { type: 'array', items: { type: 'string' } },
    buying_signals: { type: 'array', items: { type: 'string' } },
    icp_fit_score: { type: 'integer' },
    score_reasoning: { type: 'string' }
  },
  required: ['industry','tech_stack_signals','pain_points','buying_signals','icp_fit_score','score_reasoning'],
  additionalProperties: false
};
const companyInfo = `Company: ${$json.company_name}
Domain: ${$json.domain}
LinkedIn: ${$json.linkedin_url}
Source: ${$json.source}`;
const enrichment = $json.enrichment_content ? `

Enrichment content: ${$json.enrichment_content}` : '';
const user = `${companyInfo}${enrichment}

Provide a JSON object matching this schema exactly (no extra text). Schema: ${JSON.stringify(schema)}`;
return [{ json: { messages: [ { role: 'system', content: system }, { role: 'user', content: user } ], company_name: $json.company_name, domain: $json.domain } }];

// Parse Anthropic Messages API response, extract JSON payload, and attach fields for DB update
const resp = items[0].json || {};
let text = '';
if (resp.completion && Array.isArray(resp.completion.content)) {
  const part = resp.completion.content.find(c => c.type === 'output_text') || resp.completion.content[0];
  text = part && part.text ? part.text : (typeof resp.completion.content === 'string' ? resp.completion.content : '');
} else if (resp.completion && resp.completion.content && typeof resp.completion.content === 'string') {
  text = resp.completion.content;
} else if (resp.output_text) {
  text = resp.output_text;
} else if (resp.text) {
  text = resp.text;
}
text = (text || '').trim();
let data = null;
try {
  data = JSON.parse(text);
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/m);
  if (m) {
    try { data = JSON.parse(m[0]); } catch (e2) { data = null; }
  }
}
const out = { raw_claude_response: resp, lead_summary_raw: text };
if (data) {
  out.industry = data.industry || null;
  out.tech_stack_signals = data.tech_stack_signals || null;
  out.pain_points = data.pain_points || null;
  out.buying_signals = data.buying_signals || null;
  out.icp_fit_score = data.icp_fit_score || null;
  out.score_reasoning = data.score_reasoning || null;
}
out.domain = $json.domain || $json[0]?.domain || null;
out.company_name = $json.company_name || null;
return [{ json: out }];

// Build Slack message including enriched lead fields and any outreach drafts
const lead = $json;
const lines = [];
lines.push(`*${lead.company_name || 'Unknown company'}* (${lead.domain || 'no-domain'})`);
if (lead.industry) lines.push(`Industry: ${lead.industry}`);
if (lead.icp_fit_score !== undefined && lead.icp_fit_score !== null) lines.push(`ICP score: ${lead.icp_fit_score}`);
if (lead.score_reasoning) lines.push(`Reasoning: ${lead.score_reasoning}`);
if (lead.lead_summary_raw) lines.push(`Summary: 
${lead.lead_summary_raw}`);
if (lead.subject_line) { lines.push(`
*Outreach Draft*
Subject: ${lead.subject_line}
${lead.opening_hook || ''}
${lead.email_body || ''}`); }
return [{ json: { text: lines.join('
') } }];

// Check if icp_fit_score is high enough for outreach drafting using env threshold
const score = $json.icp_fit_score || 0;
const threshold = parseInt(process.env.ICP_SCORE_THRESHOLD || '70', 10);
return [{ json: { high_score: score >= threshold, icp_fit_score: score, domain: $json.domain, company_name: $json.company_name, pain_points: $json.pain_points, buying_signals: $json.buying_signals } }];

// Build personalization prompt messages using the personalization system instructions and lead context
const system = `You are a sales personalization assistant. Create outreach content for a qualified lead using the company profile, pain points, and buying signals. Return exactly the fields subject_line, opening_hook, email_body, and linkedin_dm as valid JSON with no extra text.`;
const user = `Company: ${$json.company_name}
Pain points: ${JSON.stringify($json.pain_points || [])}
Buying signals: ${JSON.stringify($json.buying_signals || [])}
Domain: ${$json.domain}

Return the outreach fields as JSON matching the required schema exactly.`;
return [{ json: { messages: [ { role: 'system', content: system }, { role: 'user', content: user } ], domain: $json.domain } }];

// Parse personalization response, extract JSON fields and forward for DB update
const resp = items[0].json || {};
let text = '';
if (resp.completion && Array.isArray(resp.completion.content)) {
  const part = resp.completion.content.find(c => c.type === 'output_text') || resp.completion.content[0];
  text = part && part.text ? part.text : (typeof resp.completion.content === 'string' ? resp.completion.content : '');
} else if (resp.output_text) {
  text = resp.output_text;
} else if (resp.text) {
  text = resp.text;
}
text = (text || '').trim();
let data = null;
try { data = JSON.parse(text); } catch (e) { const m = text.match(/\{[\s\S]*\}/m); if (m) { try { data = JSON.parse(m[0]); } catch (e2) { data = null; } } }
const out = { raw_personalization_response: resp, personalization_raw: text };
if (data) { out.subject_line = data.subject_line || null; out.opening_hook = data.opening_hook || null; out.email_body = data.email_body || null; out.linkedin_dm = data.linkedin_dm || null; }
out.domain = $json.domain || null;
return [{ json: out }];

// Normalize Apollo results into multiple items that match the Normalize Input shape
const resp = items[0].json || {};
const companies = resp.organizations || resp.results || [];
const out = companies.map(c => ({ json: { company_name: c.name || c.org_name || '', domain: c.website || c.domain || '', linkedin_url: c.linkedin_url || c.linkedin || '', source: 'apollo' } }));
return out;

// Attach enrichment HTML/text into the item for the Claude prompt
const resp = items[0].json || {};
const scraped = resp.scrape_text || resp.html || JSON.stringify(resp);
return [{ json: { ...$json, enrichment_content: scraped } }];

// Format an error object for alerting
const e = items[0].json || {};
const text = `Workflow error: ${e.errorMessage || JSON.stringify(e)}`;
return [{ json: { text } }];
